import{u as n,C as s,o as t,c as r,j as a,a as o,E as d,k as h,e as u,al as c}from"./chunks/framework.7vp1BMOE.js";const f={key:0},b=JSON.parse('{"title":"PX4-Autopilot Main Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"ko/releases/main.md","filePath":"ko/releases/main.md"}'),m={name:"ko/releases/main.md"},P=Object.assign(m,{setup(p){const{site:i}=n();return(g,e)=>{const l=s("Badge");return t(),r("div",null,[e[1]||(e[1]=a("h1",{id:"px4-autopilot-main-release-notes",tabindex:"-1"},[o("PX4-Autopilot Main Release Notes "),a("a",{class:"header-anchor",href:"#px4-autopilot-main-release-notes","aria-label":'Permalink to "PX4-Autopilot Main Release Notes"'},"​")],-1)),d(l,{type:"danger",text:"Alpha"}),h(i).title!=="PX4 Guide (main)"?(t(),r("div",f,[...e[0]||(e[0]=[a("div",{class:"custom-block danger"},[a("p",{class:"custom-block-title"},[o("This page is on a release branch, and hence probably out of date. "),a("a",{href:"https://docs.px4.io/main/en/releases/main"},"See the latest version"),o(".")])],-1)])])):u("",!0),e[2]||(e[2]=c('<p>This contains changes to the PX4 <code>main</code> branch that are not included in the next release (<a href="./../releases/1.18">PX4 v1.18</a>).</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>PX4 v1.18 is in beta testing. Update these notes with features that are going to be in <code>main</code> (PX4 v2.0 or later) but not the PX4 v1.18 release.</p></div><h2 id="read-before-upgrading" tabindex="-1">Read Before Upgrading <a class="header-anchor" href="#read-before-upgrading" aria-label="Permalink to &quot;Read Before Upgrading&quot;">​</a></h2><p>Please continue reading for <a href="#upgrade-guide">upgrade instructions</a>.</p><h2 id="major-changes" tabindex="-1">Major Changes <a class="header-anchor" href="#major-changes" aria-label="Permalink to &quot;Major Changes&quot;">​</a></h2><ul><li><strong><a href="./../config/motor_failure_recovery">Motor failure recovery for hexarotors</a>.</strong> On a detected single motor failure the control allocator removes the failed motor and, on a hexarotor, additionally stops (<a href="./../advanced_config/parameter_reference#CA_FAILURE_MODE">CA_FAILURE_MODE</a> = <code>1</code>) or reverses (<code>2</code>) the motor opposite it, recovering the yaw authority that is otherwise lost. Reversing keeps the opposite motor in the allocation and needs a reverse-capable ESC; the reverse thrust the allocator expects from a forward propeller is set with <a href="./../advanced_config/parameter_reference#CA_REV_THR_FRAC">CA_REV_THR_FRAC</a> (default <code>0.4</code>). Disabled by default. (<a href="https://github.com/PX4/PX4-Autopilot/pull/28078" target="_blank" rel="noreferrer">PX4-Autopilot#28078</a>)</li></ul><h2 id="upgrade-guide" tabindex="-1">Upgrade Guide <a class="header-anchor" href="#upgrade-guide" aria-label="Permalink to &quot;Upgrade Guide&quot;">​</a></h2><ul><li><code>COM_ARM_TRAFF</code> has been replaced by <code>COM_TRAFF_AVOID</code>. The old value 3 (&quot;enforce for mission modes only&quot;) is migrated to <code>COM_TRAFF_AVOID=2</code>, which blocks arming in all modes, not just mission modes. If you relied on being able to arm manually with traffic detected, set <code>COM_TRAFF_AVOID=1</code> (warning only) instead.</li><li><strong>Re-check motor failure handling on hexarotors.</strong> <a href="./../advanced_config/parameter_reference#CA_FAILURE_MODE">CA_FAILURE_MODE</a> = <code>1</code> now also stops the motor opposite the failed one on a hexarotor (previously only the failed motor was removed from the allocation). Other airframes are unaffected, and <code>CA_FAILURE_MODE=0</code> (the default) is unchanged. See <a href="./../config/motor_failure_recovery">Motor Failure Recovery</a>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/28078" target="_blank" rel="noreferrer">PX4-Autopilot#28078</a>)</li></ul><h2 id="other-changes" tabindex="-1">Other changes <a class="header-anchor" href="#other-changes" aria-label="Permalink to &quot;Other changes&quot;">​</a></h2><ul><li>Fast mission Return modes (<a href="./../advanced_config/parameter_reference#RTL_TYPE">RTL_TYPE</a> = 2 and 4) now skip <code>DO_JUMP</code> commands (loops) while following the mission path. (<a href="https://github.com/PX4/PX4-Autopilot/pull/26993" target="_blank" rel="noreferrer">PX4-Autopilot#26993: fix(navigator): goToNextPositionItem skip loops when required</a>)</li></ul><h3 id="hardware-support" tabindex="-1">Hardware Support <a class="header-anchor" href="#hardware-support" aria-label="Permalink to &quot;Hardware Support&quot;">​</a></h3><ul><li>TBD</li></ul><h3 id="공통" tabindex="-1">공통 <a class="header-anchor" href="#공통" aria-label="Permalink to &quot;공통&quot;">​</a></h3><ul><li>TBD</li></ul><h3 id="제어" tabindex="-1">제어 <a class="header-anchor" href="#제어" aria-label="Permalink to &quot;제어&quot;">​</a></h3><ul><li>TBD</li></ul><h3 id="안전-설정" tabindex="-1">안전 설정 <a class="header-anchor" href="#안전-설정" aria-label="Permalink to &quot;안전 설정&quot;">​</a></h3><ul><li><a href="./../flight_modes/return#geofence_awareness">Geofence Aware Return mode</a>. (<a href="https://github.com/PX4/PX4-Autopilot/pull/27145" target="_blank" rel="noreferrer">PX4-Autopilot#27145: feat(navigator): Geofence Aware RTL</a>, <a href="https://github.com/PX4/PX4-Autopilot/pull/28001" target="_blank" rel="noreferrer">PX4-Autopilot#28001: docs(navigator): [geofence] added some more warnings about limitations</a>).</li><li><a href="./../advanced_config/flight_termination">Flight termination</a> can now be used instead of a Descent mode as a fallback failsafe mode, allowing safer landing for unpiloted vehicles that carry a parachute. See <a href="./../config/safety#battery-level-failsafe">Battery level failsafe</a> (<a href="./../advanced_config/parameter_reference#COM_LOW_BAT_ACT">COM_LOW_BAT_ACT</a>) and <a href="./../config/safety#position-loss-failsafe-action">Position Loss Failsafe Action</a> (new <a href="./../advanced_config/parameter_reference#COM_POS_FS_ACT">COM_POS_FS_ACT</a>). (<a href="https://github.com/PX4/PX4-Autopilot/pull/28064" target="_blank" rel="noreferrer">PX4-Autopilot#28064: feat(commander): add terminate options for critical battery and lost position failsafes</a>).</li><li><a href="./../debug/failure_injection">Failure injection</a> ( <a href="./../advanced_config/parameter_reference#SYS_FAILURE_EN">SYS_FAILURE_EN</a>) has been significantly extended. (PX4-Autopilot#27572, PX4-Autopilot#27832, PX4-Autopilot#27950) <ul><li>Now applied on real hardware, not just simulators (injection hooks live in the shared sensor drivers).</li><li>Command handling is centralized behind a dedicated failure-injection manager module.</li><li>Multiple sensor instances can be failed simultaneously via a bitmask, and failures can be triggered from an RC switch.</li><li>Changed default behaviour of injected WRONG failure for Batteries, to publish a wrong level, and not stop publishing</li></ul></li><li><a href="./../config/motor_failure_recovery">Motor failure recovery</a> for hexarotors: on a single motor failure the control allocator removes the failed motor and additionally stops (<a href="./../advanced_config/parameter_reference#CA_FAILURE_MODE">CA_FAILURE_MODE</a> = <code>1</code>) or reverses (<code>2</code>) the motor opposite it to recover the lost yaw authority. Mode <code>2</code> requires a reverse-capable ESC and models the reverse thrust of a forward propeller with the new <a href="./../advanced_config/parameter_reference#CA_REV_THR_FRAC">CA_REV_THR_FRAC</a> (default <code>0.4</code>). Reversible motor outputs on DroneCAN are now sent as signed <code>RawCommand</code> values (negative is reverse). (<a href="https://github.com/PX4/PX4-Autopilot/pull/28078" target="_blank" rel="noreferrer">PX4-Autopilot#28078</a>)</li><li>Added <code>RTL_TYPE=6</code> for battery-aware home priority return (<a href="https://github.com/PX4/PX4-Autopilot/pull/26968" target="_blank" rel="noreferrer">PX4-Autopilot#26968</a>). Returns to home if the estimated flight time to home is within the remaining battery time; otherwise returns to the closest rally point. Falls back to the closest safe point (home or rally) if battery time remaining is unavailable.</li></ul><h3 id="estimation" tabindex="-1">Estimation <a class="header-anchor" href="#estimation" aria-label="Permalink to &quot;Estimation&quot;">​</a></h3><ul><li>TBD</li></ul><h3 id="센서" tabindex="-1">센서 <a class="header-anchor" href="#센서" aria-label="Permalink to &quot;센서&quot;">​</a></h3><ul><li>Enable <a href="./../gps_compass/u-center">u-blox Diagnostics with u-center</a> while the vehicle&#39;s GPS runs as usual. (<a href="https://github.com/PX4/PX4-Autopilot/pull/28280" target="_blank" rel="noreferrer">PX4-Autopilot#28280</a>).</li></ul><h3 id="시뮬레이션" tabindex="-1">시뮬레이션 <a class="header-anchor" href="#시뮬레이션" aria-label="Permalink to &quot;시뮬레이션&quot;">​</a></h3><ul><li>TBD</li></ul><h3 id="debug-logging" tabindex="-1">Debug &amp; Logging <a class="header-anchor" href="#debug-logging" aria-label="Permalink to &quot;Debug &amp; Logging&quot;">​</a></h3><ul><li>TBD</li></ul><h3 id="ethernet" tabindex="-1">Ethernet <a class="header-anchor" href="#ethernet" aria-label="Permalink to &quot;Ethernet&quot;">​</a></h3><ul><li>TBD</li></ul><h3 id="uxrce-dds-zenoh-ros-2" tabindex="-1">uXRCE-DDS / Zenoh / ROS 2 <a class="header-anchor" href="#uxrce-dds-zenoh-ros-2" aria-label="Permalink to &quot;uXRCE-DDS / Zenoh / ROS 2&quot;">​</a></h3><ul><li>TBD</li></ul><h3 id="mavlink" tabindex="-1">MAVLink <a class="header-anchor" href="#mavlink" aria-label="Permalink to &quot;MAVLink&quot;">​</a></h3><ul><li>TBD</li></ul><h3 id="rc" tabindex="-1">RC <a class="header-anchor" href="#rc" aria-label="Permalink to &quot;RC&quot;">​</a></h3><ul><li>TBD</li></ul><h3 id="multi-rotor" tabindex="-1">Multi-Rotor <a class="header-anchor" href="#multi-rotor" aria-label="Permalink to &quot;Multi-Rotor&quot;">​</a></h3><ul><li>TBD</li></ul><h3 id="수직이착륙기-vtol" tabindex="-1">수직이착륙기(VTOL) <a class="header-anchor" href="#수직이착륙기-vtol" aria-label="Permalink to &quot;수직이착륙기(VTOL)&quot;">​</a></h3><ul><li>TBD</li></ul><h3 id="fixed-wing" tabindex="-1">Fixed-wing <a class="header-anchor" href="#fixed-wing" aria-label="Permalink to &quot;Fixed-wing&quot;">​</a></h3><ul><li>TBD</li></ul><h3 id="rover" tabindex="-1">Rover <a class="header-anchor" href="#rover" aria-label="Permalink to &quot;Rover&quot;">​</a></h3><ul><li>TBD</li></ul><h3 id="ros-2" tabindex="-1">ROS 2 <a class="header-anchor" href="#ros-2" aria-label="Permalink to &quot;ROS 2&quot;">​</a></h3><ul><li>TBD</li></ul>',44))])}}});export{b as __pageData,P as default};
